head.script:
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#floatingLayer1_resize', 'drag-n-drop', {
        dx: 160,
        dy: 60
    });
}
scwin.checktype = function() {
    return typeof WebSquare.wUnit.getObjById('floatingLayer1_resize');
}
scwin.checktype2 = function() {
    return scwin.checktype() == 'object';
}
scwin.checkVal = function() {
    return WebSquare.wUnit.getJq('#floatingLayer1').css('width') != widthInit;
}
scwin.checkVal1 = function() {
    return widthInit = WebSquare.wUnit.getJq('#floatingLayer1').css('width');
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 3. 2번의 샘플파일을 실행 후 floatingLayer_dragResizable창을 마우스로 크기를 조절한다.
    //3. After executing sample file 2, resize floatingLayer_dragResizable window with mouse.
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("assert", "scwin.checktype2()", "true");
    WebSquare.wUnit.addCommand("set", "scwin.checkVal1()");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "100");
    //Verify step 3. floatingLayer_dragResizable창의 크기가 조절된다.
    //3. floatingLayer_dragResizable The window is resized.
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 28-Mar-2018
    window.widthInit = undefined;
    //end
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
